package java_basics;

public class Unary {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int a=5;
		
		System.out.println(++a);//pre increment 1st increment then assign
		System.out.println(--a);//pre decrement 1st decrement then assign
		
		System.out.println(a++);//post increment 1st assign then increment
		System.out.println(a--);//post decrement 1st assign then decrement
	}

}
